```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*)/2 n_abn, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') AND attr_span_kind IN ('Client','Server') AND service_name IN ('search','rate','geo') GROUP BY 1,2,3 ORDER BY 2,1",
          "claim": "search's client span to rate.GetRates has p95 ~2.9s, while rate's server span stays ~1ms; geo calls stay ~0.6ms."
        },
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id cid, time ct, duration cd FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client'), r AS (SELECT trace_id, parent_span_id, time rt, duration rd FROM abnormal_traces WHERE service_name='rate' AND attr_span_kind='Server') SELECT round(avg(epoch(rt)-epoch(ct))*1000,1) avg_start_lag_ms, round(avg(epoch(ct)+cd/1e9-(epoch(rt)+rd/1e9))*1000,1) avg_end_lag_ms, count(*) n FROM c JOIN r ON r.parent_span_id=c.cid",
          "claim": "The ~1.6s delay is before rate receives the request; the response returns with no lag, so the wait is on the caller side."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*)/2 n, round(approx_quantile(duration/1e6,0.5),2) p50, round(approx_quantile(duration/1e6,0.95),2) p95 FROM normal_traces WHERE span_name='rate.Rate/GetRates' AND attr_span_kind='Client' AND service_name='search' GROUP BY 1,2,3,4",
          "claim": "Normal period: search's client span to rate.GetRates had p95 ~1.3ms, versus ~2.9s during the incident."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*)/2 n_abn, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='frontend' AND (span_name IN ('search.Search/Nearby','HTTP /hotels')) GROUP BY 1,2,3 ORDER BY 2",
          "claim": "frontend's search.Search/Nearby client calls and HTTP /hotels server spans both show p95 ~2.9s, matching search's delay."
        }
      ]
    }
  ]
}
```

